<template><BaseLayout pageTitle="Tools"><template #body><ReferralForm v-if="referralOpen" @close="referralOpen=false"/><main v-else class="tools"><button v-if="supportOpen" type="button" class="tools-back" @click="backSupport">‹ Back to {{ fleetOpen ? 'Support' : 'Tools' }}</button><h1>{{ fleetOpen ? 'Fleet Support' : supportOpen ? 'Support' : 'How can we help?' }}</h1><p>{{ supportOpen ? 'Choose the support you need.' : 'Choose a tool to get started. Hold a card to rearrange.' }}</p><div class="tool-grid"><button v-for="item in (fleetOpen ? fleetItems : supportOpen ? supportItems : orderedItems)" :key="item.title" :data-tool="item.title" :class="{dragging:dragging===item.title}" type="button" @pointerdown="press($event,item.title)" @pointermove="move" @pointerup="release" @pointercancel="cancel" @contextmenu.prevent @click="openTool(item.title)" @keydown.alt.left.prevent="shift(item.title,-1)" @keydown.alt.right.prevent="shift(item.title,1)"><span class="tool-icon"><FeatherIcon :name="item.icon"/></span><strong>{{ item.title }}</strong><small>{{ item.note }}</small><span v-if="!['Recommend a friend for £250','Support','Payment Support','Fleet Support','FNOL','SOD – Start of Day','Leave / Holidays','Notice / Offboarding'].includes(item.title)" class="soon">Coming soon</span></button></div><div v-if="selected" class="tool-notice" role="status"><strong>{{ selected }}</strong><p>This tool will be available once its link has been added.</p><button type="button" @click="selected=''">Dismiss</button></div><Teleport to="body"><div v-if="fnolOpen" :style="{top: previewMode ? '44px' : '0'}" class="fnol-overlay" role="dialog" aria-modal="true" aria-labelledby="fnol-title" @keydown.esc="fnolOpen=false"><header><button type="button" @click="fnolOpen=false">‹ Back</button><h2 id="fnol-title">{{ formTitle }}</h2><button type="button" @click="formHome">Home</button></header><p v-if="formTitle==='Report a vehicle incident'">Check your prefilled details before submitting. The pass-date field is prefilled from your licence issue date; please check it.</p><p v-if="formTitle==='SOD – Start of Day' && sdtTestContact">Testing with the selected associate’s Contact Name. Your profile is unchanged.</p><iframe :src="fnolSource" :title="formTitle" referrerpolicy="no-referrer" allow="camera" /></div></Teleport></main></template></BaseLayout></template>
<script setup>
import {ref,computed,onBeforeUnmount} from 'vue'
import {useRouter} from 'vue-router'
import {fnolUrl} from '@/utils/fnolPrefill'
import {onboarding} from '@/data/onboarding'
import ReferralForm from '@/components/ReferralForm.vue'
import BaseLayout from '@/components/BaseLayout.vue'
import {FeatherIcon} from 'frappe-ui'
const previewMode=['127.0.0.1','localhost'].includes(window.location.hostname)
const router=useRouter()
function formHome(){fnolOpen.value=false;router.push('/home')}
// Retained for switching back after the SDT test.
const originalSdtUrl='https://forms.onemotion.uk/app/form?id=3lsD.Q'
const sdtTestContact=previewMode?sessionStorage.getItem('sdt-test-contact-name')||'':''
const testSdtUrl='https://forms.onemotion.uk/app/form?id=S3amtQ'
const referralOpen=ref(false),supportOpen=ref(false)
function backSupport(){if(fleetOpen.value)fleetOpen.value=false;else supportOpen.value=false;selected.value=''}
const selected=ref(''),fleetOpen=ref(false),fnolOpen=ref(false),fnolSource=ref(''),formTitle=ref('')
const fleetItems=[{title:'FNOL',note:'Report a vehicle incident',icon:'file-text'},{title:'Breakdown',note:'Get help with a breakdown',icon:'alert-triangle'},{title:'Contact',note:'Get in touch with the fleet team',icon:'tool'}]
const supportItems=[{title:'Payment Support',note:'Help with payments',icon:'credit-card'},{title:'Fleet Support',note:'Help with your vehicle',icon:'truck'}]
const items=[{title:'SOD – Start of Day',note:'Open your start of day form',icon:'clipboard'},{title:'Leave / Holidays',note:'Request time away',icon:'calendar'},{title:'Support',note:'Payment and fleet support',icon:'help-circle'},{title:'Notice / Offboarding',note:'Let the team know you plan to leave',icon:'log-out'},{title:'Training',note:'Learning and training resources',icon:'book-open'},{title:'Recommend a friend for £250',note:'Refer someone to One Motion',icon:'user-plus'}]

const storageKey='tool-order:'+String(onboarding.profile?.values?.email||'local-profile')
let saved=[];try{saved=JSON.parse(localStorage.getItem(storageKey)||'[]')}catch{}
const order=ref(Array.isArray(saved)?saved.map(t=>t==='SDT'?'SOD – Start of Day':t).map(t=>['Provide Notice to Leave One Motion','Request offboarding'].includes(t)?'Notice / Offboarding':t).map(t=>['Leave / Holiday Request','Leave & Holiday Request'].includes(t)?'Leave / Holidays':t).filter(t=>items.some(i=>i.title===t)):[])
const orderedItems=computed(()=>[...order.value.map(t=>items.find(i=>i.title===t)),...items.filter(i=>!order.value.includes(i.title))])
const dragging=ref('');let timer,origin,pressed='',suppressUntil=0
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(order.value))}catch{}}
function shift(title,delta){if(supportOpen.value)return;const list=orderedItems.value.map(i=>i.title),from=list.indexOf(title),to=Math.max(0,Math.min(list.length-1,from+delta));list.splice(from,1);list.splice(to,0,title);order.value=list;persist()}
function press(event,title){if(supportOpen.value)return;if(event.pointerType==='mouse'&&event.button!==0)return;cancel();pressed=title;origin={x:event.clientX,y:event.clientY};timer=setTimeout(()=>{dragging.value=title;suppressUntil=Date.now()+1000;event.target.closest('button').setPointerCapture(event.pointerId)},450)}
function move(event){if(!dragging.value){if(origin&&Math.hypot(event.clientX-origin.x,event.clientY-origin.y)>10)cancel();return}event.preventDefault();const target=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-tool]')?.dataset.tool;if(target&&target!==dragging.value){const list=orderedItems.value.map(i=>i.title),from=list.indexOf(dragging.value),to=list.indexOf(target);list.splice(from,1);list.splice(to,0,dragging.value);order.value=list}}
function release(){if(dragging.value){persist();suppressUntil=Date.now()+600}cancel()}
function cancel(){clearTimeout(timer);dragging.value='';pressed='';origin=null}
function openTool(title){if(Date.now()<suppressUntil)return;if(title==='Recommend a friend for £250'){referralOpen.value=true;return;}if(title==='Support'){supportOpen.value=true;selected.value='';return;}if(title==='Leave / Holidays'||title==='Notice / Offboarding'){router.push({path:'/leave',query:{type:title==='Leave / Holidays'?'Holiday':'Notice'}});return}if(title==='Payment Support'){formTitle.value='New payment support ticket';fnolSource.value='https://onedesk.uk/form/emmRIvL1og70TpMS_8rOUOKu9HusSPhymwXuBsSC9v0';fnolOpen.value=true;return}if(title==='SOD – Start of Day'){formTitle.value='SOD – Start of Day';const values=onboarding.profile?.values||{};const name=String(sdtTestContact||values.contact_name||(previewMode?[values.first_name,values.middle_name,values.last_name].filter(Boolean).join(' '):'')).trim();const url=new URL(testSdtUrl);if(name)url.searchParams.set('contact_name',name);fnolSource.value=url.toString();fnolOpen.value=true;return}if(title==='FNOL'){formTitle.value='Report a vehicle incident';fnolSource.value=fnolUrl(onboarding.profile?.values||{});fnolOpen.value=true;return}if(title==='Fleet Support'){fleetOpen.value=true;selected.value='';return}selected.value=title}
onBeforeUnmount(cancel)
</script>
<style scoped>.fnol-overlay{position:fixed;inset:0;z-index:10000;background:white;display:flex;flex-direction:column;padding-top:env(safe-area-inset-top)}.fnol-overlay header{display:flex;align-items:center;justify-content:space-between;padding:1rem;border-bottom:1px solid #e3e8ee;gap:1rem}.fnol-overlay h2{font-size:1rem;font-weight:600}.fnol-overlay header button{background:#eef2f6;border:0;border-radius:8px;padding:.5rem 1rem;min-height:44px;color:#17202b}.fnol-overlay>p{font-size:.75rem;color:#687586;margin:0;padding:.6rem 1rem}.fnol-overlay iframe{flex:1;min-height:0;width:100%;border:0}
.tools-back{border:0;background:none;color:#a61d1d;min-height:44px;padding:0 0 .5rem;font-size:.85rem;cursor:pointer}.tool-grid>button{touch-action:none;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none}.tool-grid>button.dragging{outline:2px solid #a61d1d;box-shadow:0 8px 22px #0002;transform:scale(1.03)}.tools{padding:1.5rem 1rem 6rem;color:#17202b}.tools h1{font-size:1.4rem;font-weight:650;margin:0}.tools p{font-size:.85rem;color:#687586;margin:.4rem 0 1.25rem}.tool-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.8rem}.tool-grid>button{display:flex;flex-direction:column;text-align:left;align-items:flex-start;padding:1.2rem;background:white;border:1px solid #e3e8ee;border-radius:14px;box-shadow:0 3px 12px #18233305;cursor:pointer}.tool-icon{display:grid;place-items:center;background:#eef4fa;color:#486885;border-radius:10px;width:42px;height:42px;margin-bottom:1rem}.tool-icon svg{width:23px;height:23px}.tool-grid strong{font-size:.9rem}.tool-grid small{color:#687586;font-size:.75rem;line-height:1.5;margin-top:.4rem}.soon{font-size:.65rem;color:#728092;background:#f2f4f7;border-radius:20px;padding:.25rem .5rem;margin-top:1rem}.tool-notice{padding:1rem;margin-top:1rem;background:#f3f6fa;border-radius:12px}.tool-notice button{background:none;border:0;color:#a61d1d;min-height:36px;cursor:pointer}.tool-grid>button:focus-visible{outline:2px solid #2461a6;outline-offset:2px}</style>
